def solve(grid):
    import copy
    nrows = len(grid)
    ncols = len(grid[0])
    bottom = nrows - 1

    start_col = None
    for c in range(ncols):
        if grid[bottom][c] == 2:
            start_col = c
            break

    blocked_col = None
    for c in range(start_col + 1, ncols):
        if grid[bottom][c] == 3:
            h = 0
            for r in range(bottom, -1, -1):
                if grid[r][c] == 3:
                    h += 1
                else:
                    break
            if h >= 3:
                blocked_col = c
                break

    out = copy.deepcopy(grid)
    out[bottom][start_col] = 0

    if blocked_col is not None:
        out[bottom][blocked_col - 1] = 2
    else:
        out[bottom][ncols - 1] = 2
        cr, cc = 1, ncols - 2
        out[cr][cc] = 4
        out[cr - 1][cc] = 4
        out[cr + 1][cc] = 4
        out[cr][cc - 1] = 4
        out[cr][cc + 1] = 4

    return out
